  useEffect(() => {
    const checkUser = async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        router.push("/login");
      } else {
        setUser(user);
        await Promise.all([
          fetchProfile(user.id),
          fetchBookmarks(user.id)
        ]);
      }
      setLoading(false);
