import { supabase } from "@/lib/supabase";
import { notFound } from "next/navigation";
import Link from "next/link";

interface Bookmark {
  id: string;
  title: string;
  url: string;
  created_at: string;
}

interface PageProps {
  params: Promise<{
    handle: string;
  }>;
}

export default async function PublicProfilePage({ params }: PageProps) {
  const { handle } = await params;

  // 1. Fetch Profile by handle
  const { data: profile, error: profileError } = await supabase
    .from("profiles")
    .select("id, handle")
    .eq("handle", handle)
    .maybeSingle();

  if (profileError) {
    throw new Error("Failed to fetch profile");
  }

  // If handle doesn't exist, show 404
  if (!profile || !profile.handle) {
    notFound();
  }

  // 2. Fetch Public Bookmarks for this profile
  const { data: bookmarks, error: bookmarksError } = await supabase
    .from("bookmarks")
    .select("id, title, url, created_at")
    .eq("user_id", profile.id)
    .eq("is_public", true)
    .order("created_at", { ascending: false });

  if (bookmarksError) {
    throw new Error("Failed to fetch bookmarks");
  }

  return (
    <div className="min-h-screen bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-slate-50 via-slate-50 to-slate-100 p-4 sm:p-8">
