"use client";

import React, { useState, useEffect, useMemo } from "react";

interface BookmarkFormProps {
  initialData?: {
    title: string;
    url: string;
    is_public: boolean;
  };
  onSubmit: (data: { title: string; url: string; is_public: boolean }) => void;
  onCancel?: () => void;
  isLoading?: boolean;
}

export const BookmarkForm: React.FC<BookmarkFormProps> = ({
  initialData,
  onSubmit,
  onCancel,
  isLoading = false,
}) => {
  const [formData, setFormData] = useState({
    title: initialData?.title || "",
    url: initialData?.url || "",
    is_public: initialData?.is_public ?? false,
  });

  // Ensure internal state updates when initialData changes (e.g., when clicking edit)
  useEffect(() => {
    setFormData({
      title: initialData?.title || "",
      url: initialData?.url || "",
      is_public: initialData?.is_public ?? false,
    });
  }, [initialData]);

  const hasChanges = useMemo(() => {
    if (!initialData) return true; // Always allow submission for new bookmarks
    return (
      formData.title !== initialData.title ||
